    function toggleDropdown(dropdownTriggerId, dropdownBtnId, dropdownMenuId) {
      const dropdownTrigger = document.getElementById(dropdownTriggerId);
      const dropdownBtn = document.getElementById(dropdownBtnId);
      const dropdownMenu = document.getElementById(dropdownMenuId);

      function showMenu() {
        dropdownMenu.classList.remove('hidden');
        dropdownBtn.querySelector('svg').classList.add('rotate-180');
      }

      function hideMenu() {
        dropdownMenu.classList.add('hidden');
        dropdownBtn.querySelector('svg').classList.remove('rotate-180');
      }

      dropdownTrigger.addEventListener('mouseover', showMenu);
      dropdownTrigger.addEventListener('mouseleave', () => {
        setTimeout(() => {
          if (!dropdownMenu.matches(':hover') && !dropdownTrigger.matches(':hover')) {
            hideMenu();
          }
        }, 100);
      });

      dropdownMenu.addEventListener('mouseover', showMenu);
      dropdownMenu.addEventListener('mouseleave', hideMenu);
    }

